# This code has been fully generated by an AI.
"""Arena: vier Ecken, Entzerrung in Arena-Einheiten, Leerbild und Vordergrund."""

import json
from dataclasses import dataclass, field
from pathlib import Path

import cv2
import numpy as np

# Schatten: Helligkeit sinkt auf diesen Anteil, Farbe bleibt (OpenCV-Lab, 8 Bit).
SHADOW_MIN_RATIO = 0.35
SHADOW_MAX_RATIO = 0.97
SHADOW_MAX_CHROMA = 12
SHADOW_WINDOW = 7
SHADOW_MIN_TEXTURE = 9.0
SHADOW_MIN_NCC = 0.4


def order_corners(points: list[tuple[float, float]]) -> np.ndarray:
    """Sortiert vier Punkte zu oben-links, oben-rechts, unten-rechts, unten-links."""
    pts = np.asarray(points, dtype=np.float32).reshape(4, 2)
    # Nach Winkel um den Schwerpunkt sortieren, damit beliebige Klickreihenfolgen funktionieren.
    center = pts.mean(axis=0)
    angles = np.arctan2(pts[:, 1] - center[1], pts[:, 0] - center[0])
    pts = pts[np.argsort(angles)]
    start = int(np.argmin(pts.sum(axis=1)))
    return np.roll(pts, -start, axis=0)


@dataclass
class Arena:
    corners: np.ndarray
    units: float = 1000.0
    plate: np.ndarray | None = None
    _poly_cache: dict = field(default_factory=dict, repr=False)

    def __post_init__(self) -> None:
        self.corners = order_corners(self.corners)
        dst = np.array([[0, 0], [self.units, 0], [self.units, self.units], [0, self.units]], np.float32)
        self.h = cv2.getPerspectiveTransform(self.corners, dst)
        self.h_inv = np.linalg.inv(self.h)

    def to_arena(self, points: np.ndarray) -> np.ndarray:
        pts = np.asarray(points, np.float32).reshape(-1, 1, 2)
        return cv2.perspectiveTransform(pts, self.h).reshape(-1, 2)

    def to_image(self, points: np.ndarray) -> np.ndarray:
        pts = np.asarray(points, np.float32).reshape(-1, 1, 2)
        return cv2.perspectiveTransform(pts, self.h_inv).reshape(-1, 2)

    def contains(self, point_arena: np.ndarray) -> bool:
        x, y = point_arena
        return 0 <= x <= self.units and 0 <= y <= self.units

    def polygon_mask(self, shape: tuple[int, int], grow: float = 0.0) -> np.ndarray:
        key = (shape, grow)
        if key not in self._poly_cache:
            m = -grow * self.units
            square = np.array([[m, m], [self.units - m, m], [self.units - m, self.units - m],
                               [m, self.units - m]], np.float32)
            poly = self.to_image(square).astype(np.int32)
            mask = np.zeros(shape, np.uint8)
            cv2.fillPoly(mask, [poly], 1)
            self._poly_cache[key] = mask.astype(bool)
        return self._poly_cache[key]

    def inside_fraction(self, mask: np.ndarray) -> float:
        total = int(mask.sum())
        if total == 0:
            return 1.0
        return float((mask & self.polygon_mask(mask.shape)).sum()) / total

    def foreground(self, image: np.ndarray, threshold: int) -> np.ndarray:
        """Alles, was sich vom Leerbild unterscheidet, im Umfeld der Arena."""
        if self.plate is None or self.plate.shape != image.shape:
            return np.zeros(image.shape[:2], bool)
        # Lab trennt Helligkeit von Farbe, so lassen sich reine Abdunklungen als Schatten erkennen.
        a = cv2.cvtColor(cv2.GaussianBlur(image, (5, 5), 0), cv2.COLOR_BGR2LAB).astype(np.int16)
        b = cv2.cvtColor(cv2.GaussianBlur(self.plate, (5, 5), 0), cv2.COLOR_BGR2LAB).astype(np.int16)
        diff = np.abs(a - b)
        score = diff[..., 0] // 2 + diff[..., 1] + diff[..., 2]
        fg = ((score > threshold) & ~shadow_mask(a, b)).astype(np.uint8)
        kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5))
        fg = cv2.morphologyEx(fg, cv2.MORPH_OPEN, kernel)
        fg = cv2.morphologyEx(fg, cv2.MORPH_CLOSE, kernel, iterations=2)
        # Ringout muss sichtbar bleiben, Zuschauer weiter weg aber nicht.
        return fg.astype(bool) & self.polygon_mask(fg.shape, grow=0.25)

    def save(self, folder: Path) -> None:
        folder.mkdir(parents=True, exist_ok=True)
        (folder / "arena.json").write_text(json.dumps({"corners": self.corners.tolist()}))
        if self.plate is not None:
            cv2.imwrite(str(folder / "arena_plate.png"), self.plate)

    @classmethod
    def load(cls, folder: Path, units: float) -> "Arena | None":
        path = folder / "arena.json"
        if not path.exists():
            return None
        arena = cls(np.array(json.loads(path.read_text())["corners"], np.float32), units)
        plate = folder / "arena_plate.png"
        if plate.exists():
            arena.plate = cv2.imread(str(plate))
        return arena


def shadow_mask(lab: np.ndarray, plate_lab: np.ndarray) -> np.ndarray:
    """Pixel, die nur dunkler als das Leerbild sind, bei gleicher Farbe und gleicher Struktur."""
    lum, plate_lum = lab[..., 0].astype(np.float32), plate_lab[..., 0].astype(np.float32)
    ratio = lum / np.maximum(plate_lum, 1.0)
    chroma = np.abs(lab[..., 1] - plate_lab[..., 1]) + np.abs(lab[..., 2] - plate_lab[..., 2])
    shadow = (ratio > SHADOW_MIN_RATIO) & (ratio < SHADOW_MAX_RATIO) & (chroma < SHADOW_MAX_CHROMA)
    # Ein Schatten dunkelt den Teppich nur ab, ein Roboter ersetzt dessen Muster.
    k = (SHADOW_WINDOW, SHADOW_WINDOW)
    mi, mp = cv2.blur(lum, k), cv2.blur(plate_lum, k)
    cov = cv2.blur(lum * plate_lum, k) - mi * mp
    var_i = cv2.blur(lum * lum, k) - mi * mi
    var_p = cv2.blur(plate_lum * plate_lum, k) - mp * mp
    textured = var_p > SHADOW_MIN_TEXTURE
    ncc = cov / np.sqrt(np.maximum(var_i * var_p, 1e-3))
    return shadow & (~textured | (ncc > SHADOW_MIN_NCC))


def median_plate(images: list[np.ndarray]) -> np.ndarray:
    return np.median(np.stack(images), axis=0).astype(np.uint8)
